// 1. Capture the incoming webhook data safely using n8n's native JS framework
const inputData = $json.body || $json;

// 2. Extract the raw body text and contract name provided by the webhook payload
const rawText = inputData.body_text || "";
const contractName = inputData.contract_name || "Untitled_Contract";

// 3. Data Cleaning: Clean up formatting (tabs, newlines, duplicate spaces)
// This splits text by whitespace and joins it back with clean single spaces
const cleanedText = rawText.trim().replace(/\s+/g, ' ');

// 4. Token Safeguard Metric: Calculate character metrics for dashboard tracking
const charCount = cleanedText.length;

// 5. Output a structured data object back to the n8n pipeline canvas
return {
    contract_name: contractName,
    body_text: cleanedText,
    char_length: charCount,
    is_valid_format: charCount > 10
};

